    // Sinyal Tanımlamaları
    wire clk_game_logic; // Oyun mantığı için 60Hz saat
    wire clk_vga_pixel;  // VGA piksel saati (örn: 25MHz)
    wire reset_sync;     // Senkronize edilmiş reset

    // Input Handler'dan gelen işlenmiş girişler
    wire p1_move_left_debounced;
    wire p1_move_right_debounced;
    wire p1_attack_debounced;
    wire p1_confirm_debounced;
    wire p2_move_left_debounced;
    wire p2_move_right_debounced;
    wire p2_attack_debounced;
    wire game_mode_selected; // input_handler'dan gelen seçilmiş mod

    // CPU Bot'tan gelen Oyuncu 2 hareketleri (1P modunda)
    wire p2_cpu_move_left;
    wire p2_cpu_move_right;
    wire p2_cpu_attack;

    // Player FSM'lerden gelen bilgiler
    wire [9:0] p1_x_pos, p2_x_pos;
    wire [2:0] p1_current_state, p2_current_state;
    wire p1_is_attacking_active, p2_is_attacking_active; // Saldırının aktif olduğu an
    wire p1_facing_right, p2_facing_right;
    // Vuruş kutusu/hasar kutusu bilgileri (player_fsm'lerden game_logic_fsm'e)
    // Bu yapı, oyunun karmaşıklığına göre detaylandırılmalıdır.
    // Örnek olarak, aktif vuruş kutusunun başlangıç ve bitiş X koordinatları:
