    wire [9:0] p2_hitbox_x1, p2_hitbox_x2;
    // Hasar kutusu (genellikle oyuncu sprite'ı ile aynı)
    wire [9:0] p1_hurtbox_x1, p1_hurtbox_x2;
    wire [9:0] p2_hurtbox_x1, p2_hurtbox_x2;


    // Game Logic FSM'den gelen genel oyun durumu bilgileri
    wire [1:0] game_phase;          // 00:MENU, 01:COUNTDOWN, 10:GAMEPLAY, 11:GAMEOVER
    wire [2:0] countdown_value;     // Geri sayım için (3,2,1,0)
    wire [6:0] game_seconds_elapsed;
    wire [1:0] winner_info;         // 00:None, 01:P1, 10:P2, 11:Draw
    wire [2:0] p1_hp_current, p2_hp_current;
    wire [2:0] p1_bp_current, p2_bp_current;
    wire all_leds_blink_cmd; // game_logic_fsm'den led_driver'a

    // VGA Renderer'a gidecek renk bilgisi
    wire [7:0] vga_color_render_out;
    // VGA Driver'dan gelen koordinatlar
    wire [9:0] vga_current_x;
    wire [9:0] vga_current_y;
    wire vga_pixel_enable; // VGA'nın aktif çizim alanında olduğunu gösterir


    //-------------------------------------------------------------------------
    // Modül Örneklemeleri (Instantiations)
    //-------------------------------------------------------------------------

    // 1. Saat Yönetimi ve Reset Senkronizasyonu
    // Not: clock_manager_with_divider.v, clock_divider_functional.v'yi içinde barındırabilir.
    // SW1_CLK_SELECT ile 60Hz veya KEY ile saat seçimi burada yönetilir.
    // Basitlik adına, doğrudan 60Hz ve 25MHz saatlerin üretildiğini varsayalım.
    // Gerçek bir clock_manager modülü, CLK_50MHZ'den bu saatleri üretmelidir.
    // assign clk_game_logic = ... (clock_manager'dan gelecek)
    // assign clk_vga_pixel  = ... (clock_manager'dan gelecek)
    // assign reset_sync     = ~RESET_N; // Aktif yüksek reset için basit senkronizasyon gerekebilir.

    // Örnek: Doğrudan atama (gerçekte clock_manager kullanılmalı)
    clock_manager_with_divider clk_manager_inst (
        .clk_in_50mhz(CLK_50MHZ),
        .reset_in(RESET_N), // clock_manager reset alabilir
        .clk_select_key_60hz(SW1_CLK_SELECT), // Proje tanımına göre
        // .external_key_clk_in(KEY_INPUT_FOR_GAME_LOGIC), // Eğer harici bir tuşla saat sürülüyorsa
        .clk_out_game_logic(clk_game_logic),
        .clk_out_vga_pixel(clk_vga_pixel),
        .reset_out_sync(reset_sync) // Senkronize edilmiş reset çıkışı
    );

    // 2. Giriş Yöneticisi (Input Handler)
    // Sektirme önleme (debouncing) burada yapılmalıdır.
    input_handler input_handler_inst (
        .clk(clk_game_logic), // Debouncer için saat
        .reset(reset_sync),
        .p1_btn_left_raw(P1_BTN_LEFT),
        .p1_btn_right_raw(P1_BTN_RIGHT),
        .p1_btn_attack_raw(P1_BTN_ATTACK),
        .p1_btn_confirm_raw(P1_BTN_CONFIRM),
        .p2_btn_left_raw(P2_BTN_LEFT),
        .p2_btn_right_raw(P2_BTN_RIGHT),
        .p2_btn_attack_raw(P2_BTN_ATTACK),
        .sw_game_mode_raw(SW0_GAME_MODE),

        .p1_move_left_out(p1_move_left_debounced),
        .p1_move_right_out(p1_move_right_debounced),
        .p1_attack_out(p1_attack_debounced),
        .p1_confirm_out(p1_confirm_debounced),
        .p2_move_left_out(p2_move_left_debounced),
        .p2_move_right_out(p2_move_right_debounced),
        .p2_attack_out(p2_attack_debounced),
        .game_mode_out(game_mode_selected)
    );

    // 3. CPU Bot (Eğer 1P mod seçiliyse aktif olur)
    cpu_bot cpu_bot_inst (
        .clk_game_logic(clk_game_logic),
        .reset(reset_sync),
        .enable_bot(game_mode_selected), // Sadece 1P modunda aktif
        .p1_x_pos_in(p1_x_pos),          // Rakip (P1) konumu
        .p2_x_pos_in(p2_x_pos),          // Kendi (P2/CPU) konumu
        // .game_state_in(...)        // Gerekirse daha fazla oyun durumu bilgisi

        .cpu_move_left_out(p2_cpu_move_left),
        .cpu_move_right_out(p2_cpu_move_right),
        .cpu_attack_out(p2_cpu_attack)
    );

    // Oyuncu 2 için nihai hareketler (CPU veya insan)
    wire p2_final_move_left_input  = game_mode_selected ? p2_cpu_move_left  : p2_move_left_debounced;
    wire p2_final_move_right_input = game_mode_selected ? p2_cpu_move_right : p2_move_right_debounced;
    wire p2_final_attack_input     = game_mode_selected ? p2_cpu_attack     : p2_attack_debounced;

    // 4. Oyuncu 1 FSM
    player_fsm player1_fsm_inst (
        .clk_game_logic(clk_game_logic),
        .reset(reset_sync),
        .move_left_in(p1_move_left_debounced),
        .move_right_in(p1_move_right_debounced),
        .attack_in(p1_attack_debounced),
