        .initial_facing_right(1'b1),
        .opponent_x_pos(p2_x_pos),
        .opponent_is_attacking(p2_is_attacking_active),
        .opponent_hitbox_x1(p2_hitbox_x1),
        .opponent_hitbox_x2(p2_hitbox_x2),
        .got_hit_trigger(p1_got_hit_trigger_from_game_logic), // game_logic_fsm'den
        .got_blocked_trigger(p1_got_blocked_trigger_from_game_logic), // game_logic_fsm'den
        .current_hp_in(p1_hp_current), // game_logic_fsm'den
        .current_bp_in(p1_bp_current), // game_logic_fsm'den

        .player_x_pos_out(p1_x_pos),
        .player_current_state_out(p1_current_state),
        .player_is_attacking_active_out(p1_is_attacking_active),
        .player_facing_right_out(p1_facing_right),
        .player_hitbox_x1_out(p1_hitbox_x1),
        .player_hitbox_x2_out(p1_hitbox_x2),
        .player_hurtbox_x1_out(p1_hurtbox_x1), // Genellikle (p1_x_pos)
        .player_hurtbox_x2_out(p1_hurtbox_x2)  // Genellikle (p1_x_pos + PLAYER_SPRITE_W)
    );
    localparam P1_INITIAL_X_PARAM = 100;
    localparam P2_INITIAL_X_PARAM = 640 - 100 - 64; // PLAYER_SPRITE_W = 64

    // 5. Oyuncu 2 FSM
    player_fsm player2_fsm_inst (
        .clk_game_logic(clk_game_logic),
        .reset(reset_sync),
        .move_left_in(p2_final_move_left_input),
        .move_right_in(p2_final_move_right_input),
        .attack_in(p2_final_attack_input),
        .initial_x(P2_INITIAL_X_PARAM),
        .initial_facing_right(1'b0),
        .opponent_x_pos(p1_x_pos),
        .opponent_is_attacking(p1_is_attacking_active),
        .opponent_hitbox_x1(p1_hitbox_x1),
        .opponent_hitbox_x2(p1_hitbox_x2),
        .got_hit_trigger(p2_got_hit_trigger_from_game_logic),
        .got_blocked_trigger(p2_got_blocked_trigger_from_game_logic),
        .current_hp_in(p2_hp_current),
        .current_bp_in(p2_bp_current),

        .player_x_pos_out(p2_x_pos),
        .player_current_state_out(p2_current_state),
        .player_is_attacking_active_out(p2_is_attacking_active),
        .player_facing_right_out(p2_facing_right),
        .player_hitbox_x1_out(p2_hitbox_x1),
        .player_hitbox_x2_out(p2_hitbox_x2),
        .player_hurtbox_x1_out(p2_hurtbox_x1),
        .player_hurtbox_x2_out(p2_hurtbox_x2)
    );

    // 6. Oyun Mantığı FSM (Ana Oyun Yöneticisi)
    // Bu modül, vuruş tespiti, skor tutma, oyun aşamalarını yönetme gibi işlemleri yapar.
    wire p1_got_hit_trigger_from_game_logic;
    wire p1_got_blocked_trigger_from_game_logic;
    wire p2_got_hit_trigger_from_game_logic;
    wire p2_got_blocked_trigger_from_game_logic;

    game_logic_fsm game_logic_fsm_inst (
        .clk_game_logic(clk_game_logic),
        .reset(reset_sync),
        .p1_confirm_in(p1_confirm_debounced),
        .selected_mode_in(game_mode_selected),

        .p1_x_in(p1_x_pos),
        .p1_state_in(p1_current_state),
        .p1_is_attacking_active_in(p1_is_attacking_active),
        .p1_hitbox_x1_in(p1_hitbox_x1),
        .p1_hitbox_x2_in(p1_hitbox_x2),
        .p1_hurtbox_x1_in(p1_hurtbox_x1),
        .p1_hurtbox_x2_in(p1_hurtbox_x2),
        .p1_is_moving_backward_in(p1_current_state == 3'b010), // P_STATE_MOVE_B

        .p2_x_in(p2_x_pos),
        .p2_state_in(p2_current_state),
        .p2_is_attacking_active_in(p2_is_attacking_active),
        .p2_hitbox_x1_in(p2_hitbox_x1),
        .p2_hitbox_x2_in(p2_hitbox_x2),
        .p2_hurtbox_x1_in(p2_hurtbox_x1),
        .p2_hurtbox_x2_in(p2_hurtbox_x2),
        .p2_is_moving_backward_in(p2_current_state == 3'b010), // P_STATE_MOVE_B

        .game_phase_out(game_phase),
        .countdown_value_out(countdown_value),
        .game_seconds_elapsed_out(game_seconds_elapsed),
        .winner_info_out(winner_info),
        .p1_hp_out(p1_hp_current),
        .p1_bp_out(p1_bp_current),
        .p2_hp_out(p2_hp_current),
        .p2_bp_out(p2_bp_current),
        .all_leds_blink_cmd_out(all_leds_blink_cmd),

        .p1_hit_confirm_out(p1_got_hit_trigger_from_game_logic),
        .p1_block_confirm_out(p1_got_blocked_trigger_from_game_logic),
        .p2_hit_confirm_out(p2_got_hit_trigger_from_game_logic),
        .p2_block_confirm_out(p2_got_blocked_trigger_from_game_logic)
    );

    // 7. VGA Sürücüsü (Standart VGA Kontrolcüsü)
    // Bu, HSYNC, VSYNC ve piksel koordinatlarını (vga_current_x, vga_current_y) üretir.
    // Genellikle hazır bir IP veya modül olarak kullanılır.
    vga_driver vga_driver_inst (
        .pixel_clk(clk_vga_pixel),
        .reset(reset_sync),
        .h_sync_out(VGA_HS),
        .v_sync_out(VGA_VS),
        .video_on_out(vga_pixel_enable), // Aktif çizim alanı
        .pixel_x_out(vga_current_x),
        .pixel_y_out(vga_current_y)
    );

    // 8. VGA Renk Oluşturucu (Renderer)
    // Bu modül, vga_driver'dan gelen koordinatlara ve oyun durumuna göre piksel renklerini belirler.
    vga_renderer vga_renderer_inst (
        .clk_pixel(clk_vga_pixel), // Bu modülün iç mantığı kombinasyonel olabilir veya piksel saatine göre kaydedilebilir.
        .reset(reset_sync),
        .vga_x_in(vga_current_x),
        .vga_y_in(vga_current_y),
        .vga_video_enable_in(vga_pixel_enable),

        .game_phase_in(game_phase),
        .countdown_value_in(countdown_value),
        .winner_info_in(winner_info),
        .game_seconds_in(game_seconds_elapsed),
        .selected_mode_in(game_mode_selected), // Menüde 1P/2P göstermek için

        .p1_x_in(p1_x_pos),
        .p1_hp_in(p1_hp_current),
        .p1_bp_in(p1_bp_current),
        .p1_state_in(p1_current_state),
        .p1_facing_right_in(p1_facing_right),

        .p2_x_in(p2_x_pos),
        .p2_hp_in(p2_hp_current),
        .p2_bp_in(p2_bp_current),
        .p2_state_in(p2_current_state),
        .p2_facing_right_in(p2_facing_right),

        .vga_rgb_out(vga_color_render_out)
    );
    assign VGA_RGB = vga_pixel_enable ? vga_color_render_out : 8'b0; // Blanking sırasında siyah

    // 9. LED Sürücüsü
    led_driver led_driver_inst (
        .clk(clk_game_logic), // Yanıp sönme için saat
        .reset(reset_sync),
        .p1_health_in(p1_hp_current),
        .p2_health_in(p2_hp_current),
        .blink_enable_in(all_leds_blink_cmd), // game_logic_fsm'den
        .game_phase_in(game_phase), // Menüde LED'leri kapatmak için

        .p1_health_led_out(LED_P1_HEALTH),
        .p2_health_led_out(LED_P2_HEALTH),
        .all_leds_physical_out(LED_GAME_OVER_BLINK) // Bu, tüm LED'leri süren tek bir sinyal olabilir veya ayrı ayrı yönetilebilir.
    );

    // 10. 7-Segment Gösterge Sürücüsü
    seven_segment_driver seven_segment_driver_inst (
        .clk(clk_game_logic), // Multiplexing için saat
        .reset(reset_sync),
        .game_phase_in(game_phase),
        .selected_mode_in(game_mode_selected), // Menüde 1P/2P göstermek için
        .winner_info_in(winner_info),
        .game_time_in(game_seconds_elapsed),

        // Fiziksel 7-segment çıkışları
        .seg_data_0_out(SEG7_DATA_0),
        .seg_data_1_out(SEG7_DATA_1),
        .seg_data_2_out(SEG7_DATA_2),
        .seg_data_3_out(SEG7_DATA_3),
        .seg_an_out(SEG7_AN)
    );

endmodule




